{
  "block": "irq_ctrl",
  "requirements": [
    {
      "id": "IRQ-PARAM",
      "source": "interface_spec.md",
      "text": "The block works for every `N` from 2 to 32, and bits `N` and up of the `ENABLE`, `MODE` and `PENDING` registers read as zero and ignore writes."
    },
    {
      "id": "IRQ-RESET",
      "source": "interface_spec.md",
      "text": "While `rst_n` is low at a rising edge of `clk`, `ENABLE`, `MODE` and `PENDING` clear to zero and the remembered level of every source clears to zero."
    },
    {
      "id": "IRQ-REG-RW",
      "source": "interface_spec.md",
      "text": "A write to `ENABLE` or `MODE` stores `wdata` bits `N-1` to 0 in that register."
    },
    {
      "id": "IRQ-READ",
      "source": "interface_spec.md",
      "text": "A read never changes any register; `rdata` follows `addr` with no clock edge."
    },
    {
      "id": "IRQ-LEVEL",
      "source": "interface_spec.md",
      "text": "A high-level source sets its `PENDING` bit at every rising edge where its input is high."
    },
    {
      "id": "IRQ-EDGE",
      "source": "interface_spec.md",
      "text": "A rising-edge source sets its `PENDING` bit at a rising edge where its input is high and was low at the previous rising edge, so an input held high sets it once."
    },
    {
      "id": "IRQ-DETECT-DISABLED",
      "source": "interface_spec.md",
      "text": "Detection does not depend on `ENABLE`: a disabled source still sets its `PENDING` bit."
    },
    {
      "id": "IRQ-W1C",
      "source": "interface_spec.md",
      "text": "A write to `PENDING` clears each bit written 1 and leaves each bit written 0 unchanged; it never sets a bit."
    },
    {
      "id": "IRQ-ACK",
      "source": "interface_spec.md",
      "text": "A write to `CLAIM` acknowledges the source whose number is in `wdata` bits 4 to 0: that source's `PENDING` bit clears and no other bit changes; a number of `N` or more changes nothing."
    },
    {
      "id": "IRQ-SET-WINS",
      "source": "interface_spec.md",
      "text": "A source detected at the same rising edge as a write that clears its bit keeps its `PENDING` bit set, so a high-level source acknowledged while its input is still high stays pending."
    },
    {
      "id": "IRQ-MASK",
      "source": "interface_spec.md",
      "text": "`irq` is high exactly when some source has both its `PENDING` and its `ENABLE` bit set, for high-level and rising-edge sources alike."
    },
    {
      "id": "IRQ-PRIORITY",
      "source": "interface_spec.md",
      "text": "`irq_id` is the lowest-numbered source whose `PENDING` and `ENABLE` bits are both set, so source 0 has the highest priority, and it is 0 while `irq` is low."
    },
    {
      "id": "IRQ-CLAIM",
      "source": "interface_spec.md",
      "text": "A read of `CLAIM` returns `irq` in bit 31 and `irq_id` in bits 4 to 0, with every other bit zero."
    },
    {
      "id": "IRQ-LATENCY",
      "source": "interface_spec.md",
      "text": "`irq` and `irq_id` follow the registers with no clock edge, so a source detected at one rising edge drives `irq` until the next."
    }
  ],
  "items": [
    {
      "id": "t_smoke",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-RESET", "IRQ-REG-RW", "IRQ-LEVEL", "IRQ-MASK", "IRQ-CLAIM"],
      "description": "Smoke test at N=8. Stimulus: reset, write ENABLE bit 0 with MODE 0 (level), drive src[0] high for one edge, then drive src[0] low, read CLAIM, then write CLAIM with 0. Check: ENABLE reads back 1. irq rises after the detect edge. CLAIM reads 0x8000_0000 (id 0). After the acknowledge, PENDING bit 0 is clear and irq is low."
    },
    {
      "id": "t_param_sweep",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-PARAM"],
      "description": "Build and run at N=2, 8 and 32. Stimulus: write all ones to ENABLE, MODE and PENDING, and drive every src bit. Check: ENABLE, MODE and PENDING read zero in bits N and up. Bits N-1..0 match the scoreboard model."
    },
    {
      "id": "t_reset_values",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-RESET"],
      "description": "Stimulus: put nonzero values in ENABLE, MODE and PENDING and hold rising-edge sources high. Then hold rst_n low for one or more edges. Check: all three registers read zero. Next, release reset with a source still high, with MODE written to edge before the source is driven. Check: that source sets PENDING exactly once, showing the remembered level was cleared to zero."
    },
    {
      "id": "t_reg_rw",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-REG-RW", "IRQ-PARAM"],
      "description": "At N=2, 8 and 32. Stimulus: write random, walking-one and all-ones patterns to ENABLE and MODE. Check: read-back equals wdata[N-1:0], upper bits read zero, and the other register is unchanged."
    },
    {
      "id": "t_read_side_effects",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-READ"],
      "description": "Stimulus: sweep addr over 0..3 with we low for many cycles, including CLAIM reads while irq is high, and change addr between edges. Check: no register changes. rdata matches the selected register in the same cycle, sampled before the next edge."
    },
    {
      "id": "t_level_detect",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-LEVEL"],
      "description": "Stimulus: hold a level-mode source high across several edges, and clear it by W1C between edges. Check: PENDING is set again at every edge where the input is high."
    },
    {
      "id": "t_edge_detect",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-EDGE"],
      "description": "Stimulus on an edge-mode source: a single-cycle pulse, an input held high for many cycles with a W1C clear in the middle, and back-to-back toggles. Check: PENDING is set only where the input is low at one edge and high at the next, and is not set again while the input stays high."
    },
    {
      "id": "t_mode_switch",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-EDGE", "IRQ-LEVEL"],
      "description": "Stimulus: change MODE bits while sources are high or toggling. Check: at every edge after the MODE write, detection follows the new mode, as predicted by the scoreboard model. The write edge itself is not checked because the spec does not define it."
    },
    {
      "id": "t_detect_disabled",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-DETECT-DISABLED", "IRQ-MASK"],
      "description": "Stimulus: ENABLE zero; drive level and edge sources, then return them low. Check: PENDING bits are set while irq stays low. Then write ENABLE. Check: irq rises with no new source activity."
    },
    {
      "id": "t_w1c",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-W1C"],
      "description": "Stimulus: set several PENDING bits through the sources, then hold the sources low. Write random masks to PENDING, including ones bits on bits that are already zero. Check: bits written 1 clear, bits written 0 keep their value, and no zero bit becomes one."
    },
    {
      "id": "t_ack",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-ACK"],
      "description": "At N=2, 8 and 32. Stimulus: set all PENDING bits through the sources, then hold the sources low. Write CLAIM with every id 0..31 and with random values in wdata[31:5]. Check: only the bit named by wdata[4:0] clears, wdata[31:5] is ignored, and ids >= N change nothing (reachable only for N below 32)."
    },
    {
      "id": "t_set_wins",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-SET-WINS"],
      "description": "Stimulus: at the same edge as a PENDING W1C write or a CLAIM acknowledge, a level source is high or an edge source has a rising edge. Check: the bit stays set after that edge. A level source acknowledged while still high stays pending and irq stays high."
    },
    {
      "id": "t_priority",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-PRIORITY", "IRQ-MASK"],
      "description": "Stimulus: random PENDING and ENABLE combinations, plus a claim-and-acknowledge loop that services every source with the sources held low. Check: irq_id is the lowest index with PENDING and ENABLE both set, sources are serviced in ascending order, and irq_id is 0 whenever irq is low."
    },
    {
      "id": "t_claim_read",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-CLAIM"],
      "description": "Stimulus: read CLAIM with irq low and with irq high, for ids 0, N-1 and random. Check: bit 31 equals irq, bits 4..0 equal irq_id, and bits 30..5 are zero."
    },
    {
      "id": "t_random_scoreboard",
      "kind": "test",
      "file": "irq_ctrl_tb.sv",
      "proves": ["IRQ-LEVEL", "IRQ-EDGE", "IRQ-W1C", "IRQ-ACK", "IRQ-SET-WINS", "IRQ-MASK", "IRQ-PRIORITY", "IRQ-LATENCY"],
      "description": "Constrained-random src activity, register writes and reads at N=2, 8 and 32. A cycle-accurate reference model predicts ENABLE, MODE, PENDING and the remembered source levels. Check: every rdata, irq and irq_id value is compared every cycle, after each edge and before the next."
    },
    {
      "id": "a_upper_bits_zero",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-PARAM"],
      "description": "For addr 0..2, rdata bits 31 down to N are always zero. Formal run at N=2, 8 and 32."
    },
    {
      "id": "a_reset_clears",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-RESET"],
      "description": "If rst_n is low at an edge, then ENABLE, MODE, PENDING and the remembered source levels are zero after that edge."
    },
    {
      "id": "a_read_no_change",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-READ"],
      "description": "If we is low at an edge, ENABLE and MODE do not change, and PENDING only gains bits from detection. Separately, rdata always equals the register selected by addr, combinationally."
    },
    {
      "id": "a_pending_next",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-LEVEL", "IRQ-EDGE", "IRQ-DETECT-DISABLED", "IRQ-W1C", "IRQ-ACK", "IRQ-SET-WINS"],
      "description": "Per bit i, outside reset: next PENDING[i] = detect[i] | (PENDING[i] & ~clear[i]). detect is src[i] in level mode and src[i] & ~prev[i] in edge mode. clear is the W1C mask, or the acknowledge decode for ids below N. ENABLE does not appear in the term."
    },
    {
      "id": "a_no_set_by_write",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-W1C"],
      "description": "A PENDING bit goes from 0 to 1 only when detect is true for that bit, never because of a write."
    },
    {
      "id": "a_irq_mask",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-MASK", "IRQ-LATENCY"],
      "description": "irq == |(PENDING & ENABLE), checked combinationally at all times."
    },
    {
      "id": "a_irq_id",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-PRIORITY", "IRQ-LATENCY"],
      "description": "irq_id equals the lowest set index of PENDING & ENABLE, and irq_id == 0 when irq is low. Checked combinationally."
    },
    {
      "id": "a_claim_format",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-CLAIM"],
      "description": "When addr == 3: rdata[31] == irq, rdata[4:0] == irq_id, and rdata[30:5] == 0."
    },
    {
      "id": "a_regs_stable_without_write",
      "kind": "assertion",
      "file": "irq_ctrl_sva.sv",
      "proves": ["IRQ-REG-RW", "IRQ-READ"],
      "description": "Outside reset, ENABLE and MODE change only at an edge with we high and addr 0 or 1 respectively, and then take wdata[N-1:0]."
    },
    {
      "id": "c_param_n",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-PARAM"],
      "description": "Collected separately at N=2, 8 and 32: toggle coverage of all ENABLE, MODE and PENDING bits."
    },
    {
      "id": "c_mode_x_detect",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-LEVEL", "IRQ-EDGE", "IRQ-DETECT-DISABLED"],
      "description": "Cross of MODE bit (level/edge), ENABLE bit (0/1) and a detect event, per source. Also covers an edge source held high for more than one edge."
    },
    {
      "id": "c_clear_paths",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-W1C", "IRQ-ACK"],
      "description": "W1C writes with mixed 1/0 masks. Acknowledge for every id in 0..N-1, and acknowledge with an id of N or more (for N below 32)."
    },
    {
      "id": "c_set_wins",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-SET-WINS"],
      "description": "Detect and clear on the same bit at the same edge, for both W1C and acknowledge, and for both modes."
    },
    {
      "id": "c_priority",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-PRIORITY", "IRQ-MASK"],
      "description": "irq_id takes every value 0..N-1. Several candidates are active when the winner is chosen. A pending but disabled lower-numbered source sits under an enabled higher-numbered source."
    },
    {
      "id": "c_reg_access",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-REG-RW", "IRQ-READ", "IRQ-CLAIM"],
      "description": "Reads and writes to each of addr 0..3, and CLAIM reads with irq high and with irq low."
    },
    {
      "id": "c_reset_activity",
      "kind": "coverage_point",
      "file": "irq_ctrl.sv",
      "proves": ["IRQ-RESET", "IRQ-LATENCY"],
      "description": "Reset asserted while registers are nonzero and while edge sources are high. irq is high in the cycle that follows a detect edge, before the next edge."
    }
  ]
}
